WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/32.0/apex.js")}
try{
var record = new sforce.SObject("Inventory__c");
var recordSDSTS = '{!Inventory__c.SD_Accessible__c}';
var result = sforce.apex.execute('SDRequestInv', 'chkUser',{});
console.log(result);
if(result == 'Success'){
console.log('Success');
console.log('----'+recordSDSTS);

var excptioncommntsSD = prompt("Please enter your comments", ""); 
var dysSD = prompt("No. of days unit should be blocked for",); 
var noofdaysSD = parseInt(dysSD);
if(excptioncommntsSD === "" || dysSD === ""){ 
alert('Please make sure to enter comments and no. of days'); 
}
else if (Number(dysSD)){ 
excptioncommntsSD = excptioncommntsSD.substring(0,254); 
var result = sforce.apex.execute('SDRequestInv','inventoryBlockApprovalSD',{objID: "{!Inventory__c.Id}",cmmentsSD: excptioncommntsSD,blockedtillSD : noofdaysSD}); 
alert(result); 
location.reload(); 
} 
else{ 
alert('Please provide a valid value for no. of days'); 
}  

}
else{
alert("Only Sales Directors can able to block this Unit.");
}
}
catch(err){ 
txt="There was an error on this page.\n\n"; 
txt+="Error description: " + err.description + "\n\n"; 
txt+="Click OK to continue.\n\n"; 
alert(txt); 
}
